/* Generated by port_site.py from the approved mockup. Behaviour for the grow section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 9: one phone plays three screens in turn (website builds, post gets approved, Google checklist ticks). Tabs jump; the button pauses. */
  (function () {
    var sec = document.getElementById("grow"),
      scrs = [].slice.call(document.querySelectorAll("#scrn9 .scr9")),
      tabs = [].slice.call(document.querySelectorAll("#pts9 button")),
      cap = document.getElementById("cap9"),
      pp = document.getElementById("pp9"),
      ap = document.querySelector("#grow .igb9 .ap"),
      gl = [].slice.call(document.querySelectorAll("#gl9l li")),
      gn = document.getElementById("gl9n"),
      gp = document.getElementById("gl9p"),
      KEYS = ["web", "post", "google"],
      CAP = {
        web: "HAIP builds your website from your stays, photos and reviews.",
        post: "Posts drafted every week. You approve with one tap.",
        google: "A simple checklist gets you found on Google Maps.",
      },
      DUR = 6500,
      cur = 0,
      timers = [],
      adv = null,
      paused = false,
      seen = false,
      started = false,
      left = DUR,
      t0 = 0;
    var PAUSE =
        '<svg viewBox="0 0 12 12"><rect x="2" y="1.5" width="2.6" height="9" rx="1"/><rect x="7.4" y="1.5" width="2.6" height="9" rx="1"/></svg>',
      PLAY = '<svg viewBox="0 0 12 12"><path d="M3 1.5v9l7-4.5z"/></svg>';
    function at(ms, fn) {
      timers.push(ctx.setTimeout(fn, ms));
    }
    function steps(k) {
      var sc = scrs[KEYS.indexOf(k)];
      if (k === "web") {
        var it = [].slice.call(sc.querySelectorAll(".st9i"));
        it.forEach(function (e) {
          e.classList.remove("in");
        });
        it.forEach(function (e, i) {
          at(250 + i * 520, function () {
            e.classList.add("in");
          });
        });
      }
      if (k === "post") {
        ap.className = "ap";
        ap.textContent = "Approve";
        at(2600, function () {
          ap.classList.add("press");
        });
        at(2780, function () {
          ap.classList.remove("press");
          ap.classList.add("done");
          ap.textContent = "Scheduled · Fri 7 PM";
        });
      }
      if (k === "google") {
        gl.forEach(function (l, i) {
          l.classList.toggle("ok", i === 0);
        });
        gn.textContent = "5 of 8";
        gp.style.transform = "scaleX(.625)";
        at(1500, function () {
          gl[1].classList.add("ok");
          gn.textContent = "6 of 8";
          gp.style.transform = "scaleX(.75)";
        });
        at(2600, function () {
          gl[2].classList.add("ok");
          gn.textContent = "7 of 8";
          gp.style.transform = "scaleX(.875)";
        });
      }
    }
    function show(j) {
      timers.forEach(clearTimeout);
      timers = [];
      cur = (j + 3) % 3;
      var k = KEYS[cur];
      scrs.forEach(function (sc, i) {
        sc.classList.toggle("out", sc.classList.contains("on") && i !== cur);
        sc.classList.toggle("on", i === cur);
      });
      tabs.forEach(function (tb, i) {
        tb.classList.remove("on");
        if (i === cur) {
          void tb.offsetWidth;
          tb.classList.add("on");
        }
      });
      cap.textContent = CAP[k];
      if (!reduce) steps(k);
      left = DUR;
      schedule();
    }
    function schedule() {
      ctx.clearTimeout(adv);
      if (paused || !seen || reduce) return;
      t0 = Date.now();
      adv = ctx.setTimeout(function () {
        show(cur + 1);
      }, left);
    }
    function hold() {
      ctx.clearTimeout(adv);
      left = Math.max(0, left - (Date.now() - t0));
    }
    tabs.forEach(function (tb, i) {
      ctx.on(tb, "click", function () {
        show(i);
      });
    });
    ctx.on(pp, "click", function () {
      paused = !paused;
      sec.classList.toggle("paused", paused);
      pp.innerHTML = paused ? PLAY : PAUSE;
      pp.setAttribute("aria-label", paused ? "Play" : "Pause");
      if (paused) hold();
      else schedule();
    });
    if (reduce) {
      scrs.forEach(function (sc) {
        [].forEach.call(sc.querySelectorAll(".st9i"), function (e) {
          e.classList.add("in");
        });
      });
      return;
    }
    sec.style.setProperty("--d9", DUR + "ms");
    function vis(on) {
      seen = on;
      if (on && !started) {
        started = true;
        show(0);
      } else if (on) schedule();
      else hold();
    }
    if ("IntersectionObserver" in window)
      ctx
        .io(
          function (es) {
            vis(es[0].isIntersecting);
          },
          { threshold: 0.35 },
        )
        .observe(sec);
    else vis(true);
  })();
}
